CREATE TRIGGER trg_touch BEFORE UPDATE ON app.file_object FOR EACH ROW EXECUTE FUNCTION app.fn_touch();
ALTER TABLE app.file_object ENABLE ROW LEVEL SECURITY; ALTER TABLE app.file_object FORCE ROW LEVEL SECURITY;
CREATE POLICY p_tenant ON app.file_object USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE POLICY p_institution ON app.file_object AS RESTRICTIVE USING (institution_id IS NULL OR current_setting('app.institution_scope', true) = 'ALL' OR institution_id = ANY (string_to_array(NULLIF(current_setting('app.institution_ids', true), ''), ',')::uuid[])) WITH CHECK (institution_id IS NULL OR current_setting('app.institution_scope', true) = 'ALL' OR institution_id = ANY (string_to_array(NULLIF(current_setting('app.institution_ids', true), ''), ',')::uuid[]));
GRANT SELECT, INSERT, UPDATE, DELETE ON app.file_object TO edu_app;
GRANT SELECT ON app.file_object TO edu_report;
